import { useState, useEffect, useMemo } from "react";
import { auth } from "./firebase";
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from "recharts";
import { Plus, X, Loader2, ChevronDown, ChevronUp, Check, Pencil, ClipboardList, BarChart3, User, Camera, Menu as MenuIcon, Heart, Trash2, Video, Send, Paperclip, Image as ImageIcon, Link2, RefreshCw, FileText, LogOut } from "lucide-react";

// ---- Design tokens (JC brand) ----
const COLORS = {
  paper: "#F2F5F7",
  paperDeep: "#E4EAEE",
  ink: "#0D2233",
  inkDeep: "#081722",
  inkSoft: "#4C6070",
  brand: "#4394CD",
  brandDeep: "#256A98",
  brandPale: "#B9D7EB",
  muted: "#A9B7C0",
  line: "#CBD5DB",
  alert: "#D64545",
};

const CLUBS = ["Driver", "3 Wood", "5 Wood", "Hybrid", "2 Iron", "3 Iron", "4 Iron", "5 Iron", "6 Iron", "7 Iron", "8 Iron", "9 Iron", "PW", "GW", "SW", "LW", "Putter"];

const FAIRWAY_OPTIONS = [
  { key: "hit", label: "Hit" },
  { key: "left", label: "Left" },
  { key: "right", label: "Right" },
];

const GREEN_OPTIONS = [
  { key: "hit", label: "Hit" },
  { key: "left", label: "Left" },
  { key: "right", label: "Right" },
  { key: "long", label: "Long" },
  { key: "short", label: "Short" },
];

const CATEGORY_DEFS = [
  { key: "driving", label: "Driving", short: "Fairways", unit: "%", color: COLORS.brandDeep, benchmark: 55 },
  { key: "approach", label: "Approach", short: "GIR", unit: "%", color: COLORS.brand, benchmark: 45 },
  { key: "shortgame", label: "Short Game", short: "Scrambling", unit: "%", color: COLORS.brandPale, benchmark: 30 },
  { key: "putting", label: "Putting", short: "Putts/Hole", unit: "", color: COLORS.ink, benchmark: 1.8, lowerBetter: true },
];

// Benchmarks by handicap, compiled from published amateur-golfer averages
// (fairways %, GIR %, putts per round, scrambling %, avg drive yards when using driver)
const HANDICAP_BENCHMARKS = [
  { hcp: 0, fairway: 56.5, gir: 56.8, puttsRound: 31.3, scramble: 50.0, drive: 274 },
  { hcp: 5, fairway: 51.0, gir: 46.1, puttsRound: 32.5, scramble: 37.7, drive: 258 },
  { hcp: 10, fairway: 49.3, gir: 37.3, puttsRound: 33.9, scramble: 31.6, drive: 247 },
  { hcp: 15, fairway: 48.1, gir: 26.4, puttsRound: 34.8, scramble: 25.1, drive: 226 },
  { hcp: 20, fairway: 42.8, gir: 22.4, puttsRound: 36.1, scramble: 21.7, drive: 219 },
  { hcp: 25, fairway: 43.0, gir: 18.0, puttsRound: 37.0, scramble: 20.3, drive: 217 },
];

const YARDAGE_BUCKETS = [
  { label: "1-49 yds", min: 1, max: 49 },
  { label: "50-100 yds", min: 50, max: 100 },
  { label: "101-149 yds", min: 101, max: 149 },
  { label: "150-199 yds", min: 150, max: 199 },
  { label: "200+ yds", min: 200, max: Infinity },
];

function interpolateBenchmark(hcp) {
  const pts = HANDICAP_BENCHMARKS;
  const h = Math.max(pts[0].hcp, Math.min(pts[pts.length - 1].hcp, hcp));
  for (let i = 0; i < pts.length - 1; i++) {
    const a = pts[i];
    const b = pts[i + 1];
    if (h >= a.hcp && h <= b.hcp) {
      const t = b.hcp === a.hcp ? 0 : (h - a.hcp) / (b.hcp - a.hcp);
      const lerp = (k) => a[k] + (b[k] - a[k]) * t;
      return { fairway: lerp("fairway"), gir: lerp("gir"), puttsRound: lerp("puttsRound"), scramble: lerp("scramble"), drive: lerp("drive") };
    }
  }
  return pts[pts.length - 1];
}

function scoreVsBenchmark(actual, benchmark, lowerBetter) {
  if (actual == null || !isFinite(actual) || !benchmark) return null;
  const ratio = lowerBetter ? benchmark / actual : actual / benchmark;
  return Math.round(Math.max(0, Math.min(140, ratio * 100)));
}

const emptyHole = {
  number: 1,
  par: 4,
  teeClub: "Driver",
  fairway: "hit",
  driveDistance: "",
  missDistance: "",
  secondShot: "go",
  layUpClub: "7 Iron",
  layUpDistance: "",
  approachClub: "7 Iron",
  approachYardage: "",
  approachProximity: "",
  green: "hit",
  chipProximity: "",
  upDown: null,
  putts: 2,
  puttMissDistance: "",
  notes: "",
};

const JC_LOGO = "data:image/png;base64,";

const HOME_BG = "data:image/jpeg;base64,";

const REPORTS_BG = "data:image/jpeg;base64,";

function JCImage({ size = 40 }) {
  return <img src={JC_LOGO} alt="JC" width={size} height={size} style={{ display: "block", objectFit: "contain" }} />;
}

function JCBadge({ size = 40 }) {
  return <JCImage size={size} />;
}

function Tracker({ initialView }) {
  const [view, setView] = useState(initialView || "log");
  const [rounds, setRounds] = useState([]);
  const [handicap, setHandicap] = useState(null);
  const [editingHcp, setEditingHcp] = useState(false);
  const [hcpDraft, setHcpDraft] = useState("");
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [meta, setMeta] = useState({ date: new Date().toISOString().slice(0, 10), course: "", totalHoles: 18 });
  const [holes, setHoles] = useState([]);
  const [hole, setHole] = useState(emptyHole);
  const [error, setError] = useState("");
  const [expanded, setExpanded] = useState({});
  const [profile, setProfile] = useState({ photo: null, bio: "" });
  const [profileSaving, setProfileSaving] = useState(false);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const res = await window.storage.get("golf-rounds-v2", false);
        if (!cancelled && res && res.value) setRounds(JSON.parse(res.value));
      } catch (e) {
        // no saved rounds yet
      }
      try {
        const hRes = await window.storage.get("golf-handicap-v1", false);
        if (!cancelled && hRes && hRes.value) setHandicap(Number(hRes.value));
      } catch (e) {
        // no saved handicap yet
      }
      try {
        const pRes = await window.storage.get("golf-profile-info-v1", false);
        if (!cancelled && pRes && pRes.value) setProfile(JSON.parse(pRes.value));
      } catch (e) {
        // no saved profile yet
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  async function persist(next) {
    setRounds(next);
    setSaving(true);
    try {
      const ok = await window.storage.set("golf-rounds-v2", JSON.stringify(next), false);
      setError(ok ? "" : "Couldn't save — try again.");
    } catch (e) {
      setError("Couldn't save — try again.");
    } finally {
      setSaving(false);
    }
  }

  async function persistProfile(next) {
    setProfile(next);
    setProfileSaving(true);
    try {
      await window.storage.set("golf-profile-info-v1", JSON.stringify(next), false);
    } catch (e) {
      // non-critical
    } finally {
      setProfileSaving(false);
    }
  }

  function savePhoto(dataUrl) {
    persistProfile({ ...profile, photo: dataUrl });
  }

  function saveBio(bio) {
    persistProfile({ ...profile, bio });
  }

  async function saveHandicap() {
    const val = Number(hcpDraft);
    if (!hcpDraft || isNaN(val) || val < 0) return;
    setHandicap(val);
    setEditingHcp(false);
    try {
      await window.storage.set("golf-handicap-v1", String(val), false);
    } catch (e) {
      // non-critical
    }
  }

  function addHoleToDraft() {
    setHoles((prev) => [...prev, hole]);
    setHole({ ...emptyHole, number: hole.number + 1, par: 4 });
  }

  function removeDraftHole(idx) {
    setHoles((prev) => prev.filter((_, i) => i !== idx));
  }

  function finishRound() {
    if (!meta.course.trim()) {
      setError("Add a course name.");
      return;
    }
    const holeIsDirty = hole.notes || hole.putts !== 2 || hole.fairway !== "hit" || hole.green !== "hit" || hole.driveDistance || hole.approachYardage;
    const finalHoles = holeIsDirty ? [...holes, hole] : holes;
    if (finalHoles.length === 0) {
      setError("Log at least one hole.");
      return;
    }
    const round = {
      id: "r_" + Date.now(),
      date: meta.date,
      course: meta.course.trim(),
      totalHoles: Number(meta.totalHoles),
      holes: finalHoles,
    };
    persist([round, ...rounds]);
    setMeta({ date: new Date().toISOString().slice(0, 10), course: "", totalHoles: 18 });
    setHoles([]);
    setHole(emptyHole);
    setShowForm(false);
    setError("");
  }

  function removeRound(id) {
    persist(rounds.filter((r) => r.id !== id));
  }

  const allHoles = useMemo(() => rounds.flatMap((r) => r.holes), [rounds]);

  const stats = useMemo(() => {
    if (allHoles.length === 0) return null;

    const parNot3 = allHoles.filter((h) => Number(h.par) !== 3);
    const fairwayHit = parNot3.filter((h) => h.fairway === "hit").length;
    const fairwayLeft = parNot3.filter((h) => h.fairway === "left").length;
    const fairwayRight = parNot3.filter((h) => h.fairway === "right").length;

    const greenHit = allHoles.filter((h) => h.green === "hit").length;
    const greenMisses = allHoles.filter((h) => h.green !== "hit");
    const missTally = { left: 0, right: 0, long: 0, short: 0 };
    greenMisses.forEach((h) => {
      if (missTally[h.green] != null) missTally[h.green]++;
    });
    const topMissEntry = Object.entries(missTally).sort((a, b) => b[1] - a[1])[0];

    const scrambleAtt = greenMisses.filter((h) => h.upDown !== null).length;
    const scrambleHit = greenMisses.filter((h) => h.upDown === true).length;

    const totalPutts = allHoles.reduce((a, h) => a + Number(h.putts || 0), 0);
    const puttsPerHole = totalPutts / allHoles.length;

    const values = {
      driving: parNot3.length ? (fairwayHit / parNot3.length) * 100 : null,
      approach: allHoles.length ? (greenHit / allHoles.length) * 100 : null,
      shortgame: scrambleAtt ? (scrambleHit / scrambleAtt) * 100 : null,
      putting: puttsPerHole,
    };

    const gaps = CATEGORY_DEFS.map((c) => {
      const v = values[c.key];
      if (v == null) return Object.assign({}, c, { value: null, gap: -Infinity });
      const gap = c.lowerBetter ? (v - c.benchmark) / c.benchmark : (c.benchmark - v) / c.benchmark;
      return Object.assign({}, c, { value: v, gap });
    });

    const ranked = gaps.filter((g) => g.value != null).slice().sort((a, b) => b.gap - a.gap);
    const focus = ranked[0] || null;

    let focusDetail = "";
    if (focus) {
      if (focus.key === "driving" && (fairwayLeft || fairwayRight)) {
        const dir = fairwayLeft >= fairwayRight ? "left" : "right";
        focusDetail = "Missing " + dir + " most often (" + Math.max(fairwayLeft, fairwayRight) + " times).";
      } else if (focus.key === "approach" && topMissEntry && topMissEntry[1] > 0) {
        focusDetail = "Missing " + topMissEntry[0] + " most often (" + topMissEntry[1] + " times).";
      } else if (focus.key === "shortgame") {
        focusDetail = "Getting up-and-down " + scrambleHit + " of " + scrambleAtt + " times.";
      } else if (focus.key === "putting") {
        focusDetail = "Averaging " + puttsPerHole.toFixed(2) + " putts per hole.";
      }
    }

    return {
      values,
      gaps,
      focus,
      focusDetail,
      holeCount: allHoles.length,
      roundCount: rounds.length,
      missTally,
      fairwayLeft,
      fairwayRight,
    };
  }, [allHoles, rounds.length]);

  const chartData = stats
    ? stats.gaps
        .filter((g) => g.value != null)
        .map((g) => ({
          name: g.short,
          value: Number(g.value.toFixed(1)),
          isFocus: !!(stats.focus && g.key === stats.focus.key),
          unit: g.unit,
        }))
    : [];

  const missDirData = stats
    ? [
        { name: "Left", value: (stats.missTally.left || 0) + (stats.fairwayLeft || 0) },
        { name: "Right", value: (stats.missTally.right || 0) + (stats.fairwayRight || 0) },
        { name: "Long", value: stats.missTally.long || 0 },
        { name: "Short", value: stats.missTally.short || 0 },
      ]
    : [];

  if (loading) {
    return (
      <div
        style={{
          background: COLORS.paper,
          minHeight: 400,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          fontFamily: "'IBM Plex Sans', sans-serif",
          color: COLORS.inkSoft,
        }}
      >
        <Loader2 size={18} style={{ marginRight: 8, animation: "spin 1s linear infinite" }} />
        Loading your rounds…
        <style>{"@keyframes spin { to { transform: rotate(360deg); } }"}</style>
      </div>
    );
  }

  return (
    <div
      style={{
        background: COLORS.paper,
        color: COLORS.ink,
        minHeight: "100%",
        fontFamily: "'IBM Plex Sans', system-ui, sans-serif",
        paddingBottom: 60,
      }}
    >
      <style>{
        "@import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,600;9..144,700&family=IBM+Plex+Sans:wght@400;500;600&display=swap');" +
        "input, select, textarea { font-family: 'IBM Plex Sans', sans-serif; }" +
        "input:focus, select:focus, textarea:focus { outline: 2px solid " + COLORS.brandDeep + "; outline-offset: 1px; }" +
        "button:focus-visible { outline: 2px solid " + COLORS.brandDeep + "; outline-offset: 2px; }"
      }</style>

      <div
        style={{
          backgroundImage:
            "linear-gradient(180deg, rgba(13,34,51,0.35) 0%, rgba(13,34,51,0.55) 60%, " + COLORS.paper + " 100%), url(" + HOME_BG + ")",
          backgroundSize: "cover",
          backgroundPosition: "center 30%",
          padding: "20px 20px 26px",
          marginBottom: 4,
        }}
      >
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
            <JCBadge size={40} />
            <div>
              <div style={{ fontFamily: "'Fraunces', serif", fontWeight: 600, fontSize: 15, color: COLORS.paper, lineHeight: 1.1 }}>
                Joe Coyle
              </div>
              <div style={{ fontSize: 11, color: COLORS.brandPale, letterSpacing: "0.02em" }}>Golf Coaching</div>
            </div>
          </div>

          {editingHcp ? (
            <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
              <input
                type="number"
                min="0"
                step="0.1"
                autoFocus
                value={hcpDraft}
                onChange={(e) => setHcpDraft(e.target.value)}
                placeholder="HCP"
                style={{ width: 56, padding: "5px 6px", border: "1px solid " + COLORS.line, borderRadius: 4, fontSize: 13 }}
              />
              <button onClick={saveHandicap} style={{ background: COLORS.brandDeep, color: COLORS.paper, border: "none", borderRadius: 4, padding: "5px 8px", cursor: "pointer" }}>
                <Check size={13} />
              </button>
            </div>
          ) : (
            <button
              onClick={() => {
                setHcpDraft(handicap != null ? String(handicap) : "");
                setEditingHcp(true);
              }}
              style={{
                display: "flex",
                alignItems: "center",
                gap: 5,
                background: "rgba(242,245,247,0.9)",
                border: "none",
                borderRadius: 20,
                padding: "6px 12px",
                fontSize: 12,
                color: COLORS.ink,
                cursor: "pointer",
              }}
            >
              {handicap != null ? "HCP " + handicap : "Set handicap"} <Pencil size={11} />
            </button>
          )}
        </div>
      </div>

      <div style={{ padding: "0 20px" }}>
      {/* View switcher */}
      <div style={{ display: "flex", gap: 6, marginBottom: 20 }}>
        <TabButton active={view === "log"} onClick={() => setView("log")} icon={<ClipboardList size={14} />} label="Tracker" />
        <TabButton active={view === "reports"} onClick={() => setView("reports")} icon={<BarChart3 size={14} />} label="Reports" />
        <TabButton active={view === "profile"} onClick={() => setView("profile")} icon={<User size={14} />} label="Profile" />
      </div>

      {view === "reports" ? (
        <ReportsView allHoles={allHoles} roundCount={rounds.length} handicap={handicap} />
      ) : view === "profile" ? (
        <ProfileView
          rounds={rounds}
          allHoles={allHoles}
          handicap={handicap}
          editingHcp={editingHcp}
          hcpDraft={hcpDraft}
          setHcpDraft={setHcpDraft}
          saveHandicap={saveHandicap}
          setEditingHcp={setEditingHcp}
          profile={profile}
          onSavePhoto={savePhoto}
          onSaveBio={saveBio}
          profileSaving={profileSaving}
          removeRound={removeRound}
          expanded={expanded}
          setExpanded={setExpanded}
        />
      ) : (
        <>
          <h1 style={{ fontFamily: "'Fraunces', serif", fontWeight: 600, fontSize: 28, margin: "0 0 6px", letterSpacing: "-0.01em" }}>
            Round Card
          </h1>
          <p style={{ margin: "0 0 24px", color: COLORS.inkSoft, fontSize: 14, maxWidth: 480 }}>
            Log each hole — club, miss direction, yardage, putts, notes. We'll flag the part of your game costing you the most strokes.
          </p>

          {stats && stats.focus && (
            <div style={{ background: COLORS.ink, color: COLORS.paper, borderRadius: 4, padding: "16px 18px", marginBottom: 22 }}>
              <div style={{ fontSize: 12, color: COLORS.muted, marginBottom: 4 }}>
                Priority to work on · {stats.roundCount} round{stats.roundCount > 1 ? "s" : ""}, {stats.holeCount} holes logged
              </div>
              <div style={{ display: "flex", alignItems: "baseline", gap: 10, flexWrap: "wrap" }}>
                <span style={{ fontFamily: "'Fraunces', serif", fontSize: 26, fontWeight: 600 }}>{stats.focus.label}</span>
                <span style={{ fontSize: 14, color: COLORS.muted }}>
                  {stats.focus.value.toFixed(stats.focus.key === "putting" ? 2 : 1)}
                  {stats.focus.unit} vs {stats.focus.benchmark}
                  {stats.focus.unit} target
                </span>
              </div>
              {stats.focusDetail && <div style={{ fontSize: 13, color: COLORS.paper, marginTop: 6 }}>{stats.focusDetail}</div>}
            </div>
          )}

          {stats && chartData.length > 0 && (
            <div style={{ marginBottom: 22 }}>
              <div style={{ fontSize: 12, color: COLORS.inkSoft, marginBottom: 6 }}>Your averages against target benchmarks</div>
              <ResponsiveContainer width="100%" height={190}>
                <BarChart data={chartData} margin={{ top: 4, right: 8, left: -12, bottom: 0 }}>
                  <CartesianGrid vertical={false} stroke={COLORS.line} />
                  <XAxis dataKey="name" tick={{ fill: COLORS.ink, fontSize: 12 }} axisLine={{ stroke: COLORS.line }} tickLine={false} />
                  <YAxis tick={{ fill: COLORS.inkSoft, fontSize: 11 }} axisLine={false} tickLine={false} width={30} />
                  <Tooltip
                    cursor={{ fill: COLORS.paperDeep }}
                    contentStyle={{ background: COLORS.ink, border: "none", borderRadius: 4, fontSize: 12 }}
                    labelStyle={{ color: COLORS.paper }}
                    itemStyle={{ color: COLORS.paper }}
                    formatter={(v, n, p) => [v + (p.payload.unit || ""), "Your average"]}
                  />
                  <Bar dataKey="value" radius={[3, 3, 0, 0]}>
                    {chartData.map((d, i) => (
                      <Cell key={i} fill={d.isFocus ? COLORS.brand : COLORS.muted} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          )}

          {stats && missDirData.some((d) => d.value > 0) && (
            <div style={{ marginBottom: 26 }}>
              <div style={{ fontSize: 12, color: COLORS.inkSoft, marginBottom: 6 }}>Miss tendency (fairways + greens combined)</div>
              <ResponsiveContainer width="100%" height={140}>
                <BarChart data={missDirData} layout="vertical" margin={{ top: 0, right: 16, left: 0, bottom: 0 }}>
                  <CartesianGrid horizontal={false} stroke={COLORS.line} />
                  <XAxis type="number" tick={{ fill: COLORS.inkSoft, fontSize: 11 }} axisLine={false} tickLine={false} />
                  <YAxis type="category" dataKey="name" tick={{ fill: COLORS.ink, fontSize: 12 }} axisLine={false} tickLine={false} width={44} />
                  <Tooltip
                    contentStyle={{ background: COLORS.ink, border: "none", borderRadius: 4, fontSize: 12 }}
                    labelStyle={{ color: COLORS.paper }}
                    itemStyle={{ color: COLORS.paper }}
                  />
                  <Bar dataKey="value" fill={COLORS.muted} radius={[0, 3, 3, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          )}

          {!stats && (
            <div
              style={{
                border: "1px dashed " + COLORS.line,
                borderRadius: 4,
                padding: "26px 18px",
                textAlign: "center",
                color: COLORS.inkSoft,
                marginBottom: 22,
                fontSize: 14,
              }}
            >
              No holes logged yet. Start a round below to see where your game needs work.
            </div>
          )}

          {!showForm ? (
            <button
              onClick={() => setShowForm(true)}
              style={{
                display: "flex",
                alignItems: "center",
                gap: 6,
                background: COLORS.brandDeep,
                color: COLORS.paper,
                border: "none",
                borderRadius: 4,
                padding: "10px 16px",
                fontSize: 14,
                fontWeight: 500,
                cursor: "pointer",
                marginBottom: 26,
              }}
            >
              <Plus size={16} /> Log a round
            </button>
          ) : (
            <div style={{ background: "#fff", border: "1px solid " + COLORS.line, borderRadius: 6, padding: 18, marginBottom: 26 }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
                <span style={{ fontFamily: "'Fraunces', serif", fontSize: 18, fontWeight: 600 }}>New round</span>
                <button
                  onClick={() => {
                    setShowForm(false);
                    setHoles([]);
                    setHole(emptyHole);
                    setError("");
                  }}
                  style={{ background: "none", border: "none", cursor: "pointer", color: COLORS.inkSoft }}
                >
                  <X size={18} />
                </button>
              </div>

              <FieldRow label="Course">
                <input
                  type="text"
                  value={meta.course}
                  onChange={(e) => setMeta({ ...meta, course: e.target.value })}
                  placeholder="e.g. Pebble Beach"
                  style={inputStyle}
                />
              </FieldRow>
              <div style={{ display: "flex", gap: 10 }}>
                <FieldRow label="Date" style={{ flex: 1 }}>
                  <input type="date" value={meta.date} onChange={(e) => setMeta({ ...meta, date: e.target.value })} style={inputStyle} />
                </FieldRow>
                <FieldRow label="Round length" style={{ flex: 1 }}>
                  <select value={meta.totalHoles} onChange={(e) => setMeta({ ...meta, totalHoles: e.target.value })} style={inputStyle}>
                    <option value={18}>18 holes</option>
                    <option value={9}>9 holes</option>
                  </select>
                </FieldRow>
              </div>

              {holes.length > 0 && (
                <div style={{ margin: "16px 0", borderTop: "1px solid " + COLORS.line, paddingTop: 10 }}>
                  {holes.map((h, i) => (
                    <div key={i} style={{ display: "flex", justifyContent: "space-between", fontSize: 12, color: COLORS.inkSoft, padding: "4px 0" }}>
                      <span>
                        Hole {h.number} · Par {h.par} · {h.teeClub} → {h.fairway !== "na" ? cap(h.fairway) : "—"}
                        {h.driveDistance ? " (" + h.driveDistance + "y)" : ""} · {h.approachClub} → {cap(h.green)}
                        {h.approachYardage ? " (" + h.approachYardage + "y)" : ""} · {h.putts} putt{h.putts === 1 ? "" : "s"}
                      </span>
                      <button onClick={() => removeDraftHole(i)} style={{ background: "none", border: "none", color: COLORS.alert, cursor: "pointer" }}>
                        <X size={13} />
                      </button>
                    </div>
                  ))}
                </div>
              )}

              <div style={{ background: COLORS.paper, borderRadius: 4, padding: 14, marginTop: 10 }}>
                <div style={{ fontFamily: "'Fraunces', serif", fontSize: 16, fontWeight: 600, marginBottom: 10 }}>Hole {hole.number}</div>

                <div style={{ display: "flex", gap: 10 }}>
                  <FieldRow label="Hole #" style={{ width: 70 }}>
                    <input
                      type="number"
                      min="1"
                      max="18"
                      value={hole.number}
                      onChange={(e) => setHole({ ...hole, number: Number(e.target.value) })}
                      style={inputStyle}
                    />
                  </FieldRow>
                  <FieldRow label="Par" style={{ width: 90 }}>
                    <select
                      value={hole.par}
                      onChange={(e) => setHole({ ...hole, par: Number(e.target.value), fairway: Number(e.target.value) === 3 ? "na" : hole.fairway })}
                      style={inputStyle}
                    >
                      <option value={3}>3</option>
                      <option value={4}>4</option>
                      <option value={5}>5</option>
                    </select>
                  </FieldRow>
                </div>

                {Number(hole.par) !== 3 && (
                  <>
                    <FieldRow label="Tee club">
                      <select value={hole.teeClub} onChange={(e) => setHole({ ...hole, teeClub: e.target.value })} style={inputStyle}>
                        {CLUBS.map((c) => (
                          <option key={c} value={c}>{c}</option>
                        ))}
                      </select>
                    </FieldRow>
                    <FieldRow label="Tee shot">
                      <ToggleRow options={FAIRWAY_OPTIONS} value={hole.fairway} onChange={(v) => setHole({ ...hole, fairway: v })} />
                    </FieldRow>
                    <div style={{ display: "flex", gap: 10 }}>
                      <FieldRow label="Shot distance (yds)" style={{ flex: 1 }}>
                        <input
                          type="number"
                          min="0"
                          value={hole.driveDistance}
                          onChange={(e) => setHole({ ...hole, driveDistance: e.target.value })}
                          placeholder="e.g. 245"
                          style={inputStyle}
                        />
                      </FieldRow>
                      {hole.fairway !== "hit" && (
                        <FieldRow label={"Distance " + hole.fairway + " (yds)"} style={{ flex: 1 }}>
                          <input
                            type="number"
                            min="0"
                            value={hole.missDistance}
                            onChange={(e) => setHole({ ...hole, missDistance: e.target.value })}
                            placeholder="e.g. 15"
                            style={inputStyle}
                          />
                        </FieldRow>
                      )}
                    </div>
                  </>
                )}

                {Number(hole.par) === 5 && (
                  <>
                    <FieldRow label="Second shot">
                      <ToggleRow
                        options={[{ key: "layup", label: "Lay up" }, { key: "go", label: "Go for green" }]}
                        value={hole.secondShot}
                        onChange={(v) => setHole({ ...hole, secondShot: v })}
                      />
                    </FieldRow>
                    {hole.secondShot === "layup" && (
                      <div style={{ display: "flex", gap: 10 }}>
                        <FieldRow label="Lay-up club" style={{ flex: 1 }}>
                          <select value={hole.layUpClub} onChange={(e) => setHole({ ...hole, layUpClub: e.target.value })} style={inputStyle}>
                            {CLUBS.map((c) => (
                              <option key={c} value={c}>{c}</option>
                            ))}
                          </select>
                        </FieldRow>
                        <FieldRow label="Lay-up distance (yds)" style={{ flex: 1 }}>
                          <input
                            type="number"
                            min="0"
                            value={hole.layUpDistance}
                            onChange={(e) => setHole({ ...hole, layUpDistance: e.target.value })}
                            placeholder="e.g. 220"
                            style={inputStyle}
                          />
                        </FieldRow>
                      </div>
                    )}
                  </>
                )}

                <FieldRow label="Approach club">
                  <select value={hole.approachClub} onChange={(e) => setHole({ ...hole, approachClub: e.target.value })} style={inputStyle}>
                    {CLUBS.map((c) => (
                      <option key={c} value={c}>{c}</option>
                    ))}
                  </select>
                </FieldRow>
                <FieldRow label="Yardage for approach (yds)">
                  <input
                    type="number"
                    min="0"
                    value={hole.approachYardage}
                    onChange={(e) => setHole({ ...hole, approachYardage: e.target.value })}
                    placeholder="e.g. 145"
                    style={inputStyle}
                  />
                </FieldRow>
                <FieldRow label="Approach result">
                  <ToggleRow
                    options={GREEN_OPTIONS}
                    value={hole.green}
                    onChange={(v) => setHole({ ...hole, green: v, upDown: v === "hit" ? null : hole.upDown })}
                  />
                </FieldRow>
                {hole.green === "hit" && (
                  <FieldRow label="Proximity to hole (ft)">
                    <input
                      type="number"
                      min="0"
                      value={hole.approachProximity}
                      onChange={(e) => setHole({ ...hole, approachProximity: e.target.value })}
                      placeholder="e.g. 18"
                      style={inputStyle}
                    />
                  </FieldRow>
                )}

                {hole.green !== "hit" && (
                  <>
                    <FieldRow label="Chip proximity to hole (ft)">
                      <input
                        type="number"
                        min="0"
                        value={hole.chipProximity}
                        onChange={(e) => setHole({ ...hole, chipProximity: e.target.value })}
                        placeholder="e.g. 4"
                        style={inputStyle}
                      />
                    </FieldRow>
                    <FieldRow label="Up-and-down?">
                      <ToggleRow
                        options={[{ key: "true", label: "Yes" }, { key: "false", label: "No" }]}
                        value={hole.upDown === null ? "" : String(hole.upDown)}
                        onChange={(v) => setHole({ ...hole, upDown: v === "true" })}
                      />
                    </FieldRow>
                  </>
                )}

                <FieldRow label="Putts">
                  <input type="number" min="0" value={hole.putts} onChange={(e) => setHole({ ...hole, putts: Number(e.target.value) })} style={inputStyle} />
                </FieldRow>
                {Number(hole.putts) >= 2 && (
                  <FieldRow label="How far left after first putt (ft)">
                    <input
                      type="number"
                      min="0"
                      value={hole.puttMissDistance}
                      onChange={(e) => setHole({ ...hole, puttMissDistance: e.target.value })}
                      placeholder="e.g. 3"
                      style={inputStyle}
                    />
                  </FieldRow>
                )}
                <FieldRow label="Notes">
                  <textarea
                    value={hole.notes}
                    onChange={(e) => setHole({ ...hole, notes: e.target.value })}
                    placeholder="e.g. pulled it into the bunker, ball above feet"
                    rows={2}
                    style={{ ...inputStyle, resize: "vertical" }}
                  />
                </FieldRow>

                <button
                  onClick={addHoleToDraft}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 6,
                    background: "#fff",
                    border: "1px solid " + COLORS.brandDeep,
                    color: COLORS.brandDeep,
                    borderRadius: 4,
                    padding: "8px 14px",
                    fontSize: 13,
                    fontWeight: 500,
                    cursor: "pointer",
                    marginTop: 6,
                  }}
                >
                  <Check size={14} /> Save hole {hole.number}, next hole
                </button>
              </div>

              {error && <div style={{ color: COLORS.alert, fontSize: 13, marginTop: 10 }}>{error}</div>}

              <button
                onClick={finishRound}
                disabled={saving}
                style={{
                  marginTop: 14,
                  width: "100%",
                  background: COLORS.brandDeep,
                  color: COLORS.paper,
                  border: "none",
                  borderRadius: 4,
                  padding: "11px 16px",
                  fontSize: 14,
                  fontWeight: 500,
                  cursor: "pointer",
                }}
              >
                {saving ? "Saving…" : "Finish round (" + (holes.length + (hole.notes || hole.putts !== 2 ? 1 : 0)) + " holes)"}
              </button>
            </div>
          )}

          {rounds.length > 0 && (
            <div>
              <div style={{ fontSize: 12, color: COLORS.inkSoft, marginBottom: 8 }}>Round history</div>
              {rounds.map((r) => (
                <RoundRow
                  key={r.id}
                  round={r}
                  onRemove={() => removeRound(r.id)}
                  expanded={!!expanded[r.id]}
                  toggle={() => setExpanded({ ...expanded, [r.id]: !expanded[r.id] })}
                />
              ))}
            </div>
          )}
        </>
      )}

      <div style={{ marginTop: 36, paddingTop: 14, borderTop: "1px solid " + COLORS.line, fontSize: 11, color: COLORS.inkSoft, textAlign: "center" }}>
        Joe Coyle · Joe@jc60.co.uk
      </div>
      </div>
    </div>
  );
}

function TabButton({ active, onClick, icon, label }) {
  return (
    <button
      onClick={onClick}
      style={{
        display: "flex",
        alignItems: "center",
        gap: 6,
        background: active ? COLORS.ink : "#fff",
        color: active ? COLORS.paper : COLORS.inkSoft,
        border: "1px solid " + (active ? COLORS.ink : COLORS.line),
        borderRadius: 20,
        padding: "7px 14px",
        fontSize: 13,
        fontWeight: 500,
        cursor: "pointer",
      }}
    >
      {icon} {label}
    </button>
  );
}


function ReportsView({ allHoles, roundCount, handicap }) {
  const [category, setCategory] = useState("driving");
  const report = useMemo(() => {
    if (allHoles.length === 0) return null;

    const parNot3 = allHoles.filter((h) => Number(h.par) !== 3);
    const fairwayHit = parNot3.filter((h) => h.fairway === "hit").length;
    const fairwayLeft = parNot3.filter((h) => h.fairway === "left").length;
    const fairwayRight = parNot3.filter((h) => h.fairway === "right").length;
    const fairwayPct = parNot3.length ? (fairwayHit / parNot3.length) * 100 : null;

    const driverHoles = allHoles.filter((h) => h.teeClub === "Driver" && Number(h.driveDistance) > 0);
    const avgDriveDistance = driverHoles.length ? driverHoles.reduce((a, h) => a + Number(h.driveDistance), 0) / driverHoles.length : null;

    const greenHit = allHoles.filter((h) => h.green === "hit").length;
    const girPct = allHoles.length ? (greenHit / allHoles.length) * 100 : null;

    const bucketStats = YARDAGE_BUCKETS.map((b) => {
      const inBucket = allHoles.filter((h) => {
        const y = Number(h.approachYardage);
        return y > 0 && y >= b.min && y <= b.max;
      });
      const hit = inBucket.filter((h) => h.green === "hit").length;
      return { label: b.label, hit, total: inBucket.length, pct: inBucket.length ? (hit / inBucket.length) * 100 : null };
    });

    const proximityStats = YARDAGE_BUCKETS.map((b) => {
      const inBucket = allHoles.filter((h) => {
        const y = Number(h.approachYardage);
        return y > 0 && y >= b.min && y <= b.max && h.green === "hit" && Number(h.approachProximity) > 0;
      });
      const avg = inBucket.length ? inBucket.reduce((a, h) => a + Number(h.approachProximity), 0) / inBucket.length : null;
      return { label: b.label, avg, count: inBucket.length };
    });

    const greenMisses = allHoles.filter((h) => h.green !== "hit");
    const missTally = { left: 0, right: 0, long: 0, short: 0 };
    greenMisses.forEach((h) => {
      if (missTally[h.green] != null) missTally[h.green]++;
    });
    const missedGreensTotal = greenMisses.length;

    const scrambleAtt = greenMisses.filter((h) => h.upDown !== null).length;
    const scrambleHit = greenMisses.filter((h) => h.upDown === true).length;
    const scramblePct = scrambleAtt ? (scrambleHit / scrambleAtt) * 100 : null;

    const totalPutts = allHoles.reduce((a, h) => a + Number(h.putts || 0), 0);
    const puttsPerHole = allHoles.length ? totalPutts / allHoles.length : null;

    const holedPutts = allHoles.filter((h) => {
      const start = h.green === "hit" ? Number(h.approachProximity) : Number(h.chipProximity);
      return Number(h.putts) === 1 && start > 0;
    });
    const footageHoled = holedPutts.reduce((a, h) => {
      const start = h.green === "hit" ? Number(h.approachProximity) : Number(h.chipProximity);
      return a + start;
    }, 0);

    let scores = null;
    if (handicap != null) {
      const bm = interpolateBenchmark(handicap);
      const fairwayScore = scoreVsBenchmark(fairwayPct, bm.fairway, false);
      const driveScore = scoreVsBenchmark(avgDriveDistance, bm.drive, false);
      const teeScores = [fairwayScore, driveScore].filter((s) => s != null);
      const teeShots = teeScores.length ? Math.round(teeScores.reduce((a, b) => a + b, 0) / teeScores.length) : null;

      const ironPlay = scoreVsBenchmark(girPct, bm.gir, false);
      const chipping = scoreVsBenchmark(scramblePct, bm.scramble, false);
      const putting = scoreVsBenchmark(puttsPerHole, bm.puttsRound / 18, true);

      scores = { teeShots, ironPlay, chipping, putting, benchmark: bm };
    }

    return {
      fairwayHit,
      fairwayTotal: parNot3.length,
      fairwayPct,
      fairwayLeft,
      fairwayRight,
      avgDriveDistance,
      driverShotCount: driverHoles.length,
      greenHit,
      greenTotal: allHoles.length,
      girPct,
      bucketStats,
      proximityStats,
      missTally,
      missedGreensTotal,
      scrambleHit,
      scrambleAtt,
      scramblePct,
      puttsPerHole,
      totalPutts,
      footageHoled,
      holedPuttsCount: holedPutts.length,
      scores,
    };
  }, [allHoles, handicap]);

  if (!report) {
    return (
      <div
        style={{
          border: "1px dashed " + COLORS.line,
          borderRadius: 4,
          padding: "26px 18px",
          textAlign: "center",
          color: COLORS.inkSoft,
          marginBottom: 22,
          fontSize: 14,
        }}
      >
        No holes logged yet — log a round to generate reports.
      </div>
    );
  }

  const CATEGORIES = [
    { key: "driving", label: "Driving" },
    { key: "irons", label: "Irons" },
    { key: "chipping", label: "Chipping" },
    { key: "putting", label: "Putting" },
  ];

  return (
    <div>
      <div
        style={{
          margin: "0 -20px 16px",
          padding: "20px 20px 22px",
          backgroundImage:
            "linear-gradient(180deg, rgba(13,34,51,0.30) 0%, rgba(13,34,51,0.55) 65%, " + COLORS.paper + " 100%), url(" + REPORTS_BG + ")",
          backgroundSize: "cover",
          backgroundPosition: "center 55%",
        }}
      >
        <h1 style={{ fontFamily: "'Fraunces', serif", fontWeight: 600, fontSize: 26, margin: 0, letterSpacing: "-0.01em", color: COLORS.paper }}>
          Performance Report
        </h1>
      </div>
      <p style={{ margin: "0 0 16px", color: COLORS.inkSoft, fontSize: 13 }}>
        Based on {roundCount} round{roundCount > 1 ? "s" : ""}, {allHoles.length} holes logged.
      </p>

      <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 20 }}>
        {CATEGORIES.map((c) => (
          <TabButton key={c.key} active={category === c.key} onClick={() => setCategory(c.key)} label={c.label} />
        ))}
      </div>

      {category === "driving" && (
        <div>
          {report.scores && <ScoreBanner label="Tee Shots" score={report.scores.teeShots} handicap={handicap} />}
          <ReportRow label="Fairways hit" value={fmtFrac(report.fairwayHit, report.fairwayTotal)} />
          <ReportRow label="Fairways missed left" value={fmtFrac(report.fairwayLeft, report.fairwayTotal)} />
          <ReportRow label="Fairways missed right" value={fmtFrac(report.fairwayRight, report.fairwayTotal)} />
          <ReportRow
            label="Average drive distance (driver)"
            value={report.avgDriveDistance != null ? Math.round(report.avgDriveDistance) + " yds (" + report.driverShotCount + " shots)" : "No driver distances logged"}
          />
        </div>
      )}

      {category === "irons" && (
        <div>
          {report.scores && <ScoreBanner label="Iron Play" score={report.scores.ironPlay} handicap={handicap} />}
          <ReportRow label="Greens in regulation" value={fmtFrac(report.greenHit, report.greenTotal)} />
          {report.bucketStats.map((b) => (
            <ReportRow key={b.label} label={"GIR from " + b.label} value={b.total ? fmtFrac(b.hit, b.total) : "No shots logged"} />
          ))}
          <ReportRow label="Greens missed long" value={report.missedGreensTotal ? fmtFrac(report.missTally.long, report.missedGreensTotal) : "0/0"} />
          <ReportRow label="Greens missed short" value={report.missedGreensTotal ? fmtFrac(report.missTally.short, report.missedGreensTotal) : "0/0"} />
          <ReportRow label="Greens missed left" value={report.missedGreensTotal ? fmtFrac(report.missTally.left, report.missedGreensTotal) : "0/0"} />
          <ReportRow label="Greens missed right" value={report.missedGreensTotal ? fmtFrac(report.missTally.right, report.missedGreensTotal) : "0/0"} />
          {report.proximityStats.map((p) => (
            <ReportRow key={p.label} label={"Proximity from " + p.label} value={p.avg != null ? p.avg.toFixed(1) + " ft (" + p.count + " shots)" : "No shots logged"} />
          ))}
        </div>
      )}

      {category === "chipping" && (
        <div>
          {report.scores && <ScoreBanner label="Chipping" score={report.scores.chipping} handicap={handicap} />}
          <ReportRow
            label="Scrambling (up-and-down)"
            value={report.scrambleAtt ? fmtFrac(report.scrambleHit, report.scrambleAtt) : "No scramble attempts logged"}
          />
        </div>
      )}

      {category === "putting" && (
        <div>
          {report.scores && <ScoreBanner label="Putting" score={report.scores.putting} handicap={handicap} />}
          <ReportRow label="Average putts per hole" value={report.puttsPerHole != null ? report.puttsPerHole.toFixed(2) : "—"} />
          <ReportRow
            label="Footage holed with putts"
            value={report.holedPuttsCount ? report.footageHoled.toFixed(0) + " ft (" + report.holedPuttsCount + " one-putts)" : "No holed putt distances logged"}
          />
          <ReportRow label="Total putts logged" value={String(report.totalPutts)} />
        </div>
      )}
    </div>
  );
}

function ScoreBanner({ label, score, handicap }) {
  const color = score == null ? COLORS.muted : score >= 100 ? COLORS.brandDeep : score >= 75 ? COLORS.brand : COLORS.alert;
  return (
    <div style={{ background: COLORS.ink, borderRadius: 4, padding: "14px 16px", marginBottom: 18, display: "flex", alignItems: "baseline", justifyContent: "space-between" }}>
      <div>
        <div style={{ fontSize: 11, color: COLORS.muted, marginBottom: 2 }}>
          {handicap != null ? "Score vs. a " + handicap + " handicap benchmark" : "Set a handicap to unlock this score"}
        </div>
        <div style={{ fontFamily: "'Fraunces', serif", fontSize: 15, fontWeight: 600, color: COLORS.paper }}>{label}</div>
      </div>
      <div style={{ fontFamily: "'Fraunces', serif", fontSize: 30, fontWeight: 600, color }}>{score != null ? score : "—"}</div>
    </div>
  );
}

function ReportRow({ label, value }) {
  return (
    <div
      style={{
        display: "flex",
        justifyContent: "space-between",
        alignItems: "baseline",
        padding: "9px 0",
        borderTop: "1px solid " + COLORS.line,
        fontSize: 13,
      }}
    >
      <span style={{ color: COLORS.inkSoft }}>{label}</span>
      <span style={{ fontWeight: 500 }}>{value}</span>
    </div>
  );
}

function resizeImageFile(file, size) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("Couldn't read file"));
    reader.onload = () => {
      const img = new Image();
      img.onerror = () => reject(new Error("Couldn't read image"));
      img.onload = () => {
        const canvas = document.createElement("canvas");
        canvas.width = size;
        canvas.height = size;
        const ctx = canvas.getContext("2d");
        const scale = Math.max(size / img.width, size / img.height);
        const w = img.width * scale;
        const h = img.height * scale;
        ctx.drawImage(img, (size - w) / 2, (size - h) / 2, w, h);
        resolve(canvas.toDataURL("image/jpeg", 0.85));
      };
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
  });
}

function ProfileView({
  rounds,
  allHoles,
  handicap,
  editingHcp,
  hcpDraft,
  setHcpDraft,
  saveHandicap,
  setEditingHcp,
  profile,
  onSavePhoto,
  onSaveBio,
  profileSaving,
  removeRound,
  expanded,
  setExpanded,
}) {
  const [bioDraft, setBioDraft] = useState(profile.bio || "");
  const [photoError, setPhotoError] = useState("");

  async function handlePhotoChange(e) {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    setPhotoError("");
    try {
      const dataUrl = await resizeImageFile(file, 240);
      onSavePhoto(dataUrl);
    } catch (err) {
      setPhotoError("Couldn't process that image — try a different one.");
    }
  }

  const totalPutts = allHoles.reduce((a, h) => a + Number(h.putts || 0), 0);

  return (
    <div>
      <div style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 20 }}>
        <label
          style={{
            width: 84,
            height: 84,
            borderRadius: "50%",
            background: COLORS.paperDeep,
            border: "1px solid " + COLORS.line,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            overflow: "hidden",
            cursor: "pointer",
            flexShrink: 0,
            position: "relative",
          }}
        >
          {profile.photo ? (
            <img src={profile.photo} alt="Profile" width={84} height={84} style={{ objectFit: "cover" }} />
          ) : (
            <User size={32} color={COLORS.muted} />
          )}
          <div
            style={{
              position: "absolute",
              bottom: 0,
              width: "100%",
              background: "rgba(13,34,51,0.7)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              padding: "3px 0",
            }}
          >
            <Camera size={12} color={COLORS.paper} />
          </div>
          <input type="file" accept="image/*" onChange={handlePhotoChange} style={{ display: "none" }} />
        </label>
        <div>
          <div style={{ fontFamily: "'Fraunces', serif", fontWeight: 600, fontSize: 20 }}>Joe Coyle</div>
          <div style={{ fontSize: 12, color: COLORS.inkSoft, marginTop: 2 }}>Tap the photo to change it</div>
          {photoError && <div style={{ fontSize: 12, color: COLORS.alert, marginTop: 4 }}>{photoError}</div>}
        </div>
      </div>

      <FieldRow label="Current handicap">
        {editingHcp ? (
          <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
            <input
              type="number"
              min="0"
              step="0.1"
              autoFocus
              value={hcpDraft}
              onChange={(e) => setHcpDraft(e.target.value)}
              placeholder="HCP"
              style={{ ...inputStyle, width: 90 }}
            />
            <button onClick={saveHandicap} style={{ background: COLORS.brandDeep, color: COLORS.paper, border: "none", borderRadius: 4, padding: "8px 10px", cursor: "pointer" }}>
              <Check size={14} />
            </button>
          </div>
        ) : (
          <button
            onClick={() => {
              setHcpDraft(handicap != null ? String(handicap) : "");
              setEditingHcp(true);
            }}
            style={{
              display: "flex",
              alignItems: "center",
              gap: 6,
              background: "#fff",
              border: "1px solid " + COLORS.line,
              borderRadius: 4,
              padding: "8px 12px",
              fontSize: 14,
              color: COLORS.ink,
              cursor: "pointer",
            }}
          >
            {handicap != null ? handicap : "Not set"} <Pencil size={12} />
          </button>
        )}
      </FieldRow>

      <FieldRow label="Bio" style={{ marginTop: 14 }}>
        <textarea
          value={bioDraft}
          onChange={(e) => setBioDraft(e.target.value)}
          onBlur={() => {
            if (bioDraft !== profile.bio) onSaveBio(bioDraft);
          }}
          placeholder="A few lines about your game, goals, or playing history."
          rows={4}
          style={{ ...inputStyle, resize: "vertical" }}
        />
        <div style={{ fontSize: 11, color: COLORS.inkSoft, marginTop: 4 }}>{profileSaving ? "Saving…" : "Saved automatically when you tap away"}</div>
      </FieldRow>

      <div style={{ display: "flex", gap: 10, margin: "22px 0" }}>
        <div style={{ flex: 1, background: "#fff", border: "1px solid " + COLORS.line, borderRadius: 6, padding: "12px 14px" }}>
          <div style={{ fontSize: 11, color: COLORS.inkSoft, marginBottom: 4 }}>Rounds logged</div>
          <div style={{ fontFamily: "'Fraunces', serif", fontSize: 22, fontWeight: 600 }}>{rounds.length}</div>
        </div>
        <div style={{ flex: 1, background: "#fff", border: "1px solid " + COLORS.line, borderRadius: 6, padding: "12px 14px" }}>
          <div style={{ fontSize: 11, color: COLORS.inkSoft, marginBottom: 4 }}>Holes logged</div>
          <div style={{ fontFamily: "'Fraunces', serif", fontSize: 22, fontWeight: 600 }}>{allHoles.length}</div>
        </div>
        <div style={{ flex: 1, background: "#fff", border: "1px solid " + COLORS.line, borderRadius: 6, padding: "12px 14px" }}>
          <div style={{ fontSize: 11, color: COLORS.inkSoft, marginBottom: 4 }}>Total putts</div>
          <div style={{ fontFamily: "'Fraunces', serif", fontSize: 22, fontWeight: 600 }}>{totalPutts}</div>
        </div>
      </div>

      <div style={{ fontSize: 12, color: COLORS.inkSoft, marginBottom: 8 }}>Your rounds</div>
      {rounds.length === 0 ? (
        <div style={{ border: "1px dashed " + COLORS.line, borderRadius: 4, padding: "20px 16px", textAlign: "center", color: COLORS.inkSoft, fontSize: 13 }}>
          Rounds you log in the Tracker tab will be stored here, tied to your profile.
        </div>
      ) : (
        rounds.map((r) => (
          <RoundRow
            key={r.id}
            round={r}
            onRemove={() => removeRound(r.id)}
            expanded={!!expanded[r.id]}
            toggle={() => setExpanded({ ...expanded, [r.id]: !expanded[r.id] })}
          />
        ))
      )}
    </div>
  );
}

function fmtFrac(hit, total) {
  if (!total) return "0/0";
  const pct = ((hit / total) * 100).toFixed(1);
  return hit + "/" + total + " (" + pct + "%)";
}

function RoundRow({ round, onRemove, expanded, toggle }) {
  const fir = round.holes.filter((h) => h.par !== 3);
  const firHit = fir.filter((h) => h.fairway === "hit").length;
  const gir = round.holes.filter((h) => h.green === "hit").length;
  const putts = round.holes.reduce((a, h) => a + Number(h.putts || 0), 0);

  return (
    <div style={{ borderTop: "1px solid " + COLORS.line, padding: "10px 0" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", fontSize: 13 }}>
        <div style={{ cursor: "pointer", flex: 1 }} onClick={toggle}>
          <div style={{ fontWeight: 500 }}>{round.course}</div>
          <div style={{ color: COLORS.inkSoft, fontSize: 12 }}>
            {round.date} · {round.holes.length} holes · FIR {firHit}/{fir.length} · GIR {gir}/{round.holes.length} · Putts {putts}
          </div>
        </div>
        <button onClick={toggle} style={{ background: "none", border: "none", color: COLORS.inkSoft, cursor: "pointer", padding: 4 }}>
          {expanded ? <ChevronUp size={15} /> : <ChevronDown size={15} />}
        </button>
        <button onClick={onRemove} style={{ background: "none", border: "none", color: COLORS.inkSoft, cursor: "pointer", padding: 4 }}>
          <X size={15} />
        </button>
      </div>
      {expanded && (
        <div style={{ marginTop: 8, background: COLORS.paperDeep, borderRadius: 4, padding: 10 }}>
          {round.holes.map((h, i) => (
            <div
              key={i}
              style={{ fontSize: 12, color: COLORS.ink, padding: "4px 0", borderBottom: i < round.holes.length - 1 ? "1px solid " + COLORS.line : "none" }}
            >
              <div>
                Hole {h.number} (Par {h.par}) — {h.par !== 3 ? h.teeClub + " " + cap(h.fairway) + (h.driveDistance ? " " + h.driveDistance + "y" : "") + " · " : ""}
                {h.par === 5 && h.secondShot === "layup" ? "Lay up " + h.layUpClub + (h.layUpDistance ? " " + h.layUpDistance + "y" : "") + " · " : ""}
                {h.approachClub} {h.approachYardage ? h.approachYardage + "y " : ""}
                {cap(h.green)}
                {h.green === "hit" && h.approachProximity ? " (" + h.approachProximity + "ft)" : ""} · {h.putts} putts
                {Number(h.putts) >= 2 && h.puttMissDistance ? ", left " + h.puttMissDistance + "ft after 1st" : ""}
                {h.green !== "hit" ? " · Chip to " + (h.chipProximity ? h.chipProximity + "ft" : "?") + " · Up&down: " + (h.upDown ? "Yes" : "No") : ""}
              </div>
              {h.notes && <div style={{ color: COLORS.inkSoft, fontStyle: "italic" }}>{h.notes}</div>}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function ToggleRow({ options, value, onChange }) {
  return (
    <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
      {options.map((o) => (
        <button
          key={o.key}
          type="button"
          onClick={() => onChange(o.key)}
          style={{
            padding: "6px 12px",
            borderRadius: 4,
            border: "1px solid " + (value === o.key ? COLORS.brandDeep : COLORS.line),
            background: value === o.key ? COLORS.brandDeep : "#fff",
            color: value === o.key ? COLORS.paper : COLORS.ink,
            fontSize: 13,
            cursor: "pointer",
          }}
        >
          {o.label}
        </button>
      ))}
    </div>
  );
}

function cap(s) {
  if (!s) return "";
  return s.charAt(0).toUpperCase() + s.slice(1);
}

const inputStyle = {
  width: "100%",
  boxSizing: "border-box",
  padding: "8px 10px",
  border: "1px solid " + COLORS.line,
  borderRadius: 4,
  fontSize: 14,
  color: COLORS.ink,
  background: "#fff",
};

function FieldRow({ label, children, style }) {
  return (
    <div style={{ marginBottom: 10, ...style }}>
      <label style={{ display: "block", fontSize: 12, color: COLORS.inkSoft, marginBottom: 4 }}>{label}</label>
      {children}
    </div>
  );
}


const fontImport =
  "@import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,600;9..144,700&family=IBM+Plex+Sans:wght@400;500;600&display=swap');";
const DRILL_CATEGORIES = ["Putting", "Short Game", "Iron Play", "Driving", "Course Management"];

function toEmbedUrl(url) {
  if (!url) return null;
  const yt = url.match(/(?:youtu\.be\/|youtube\.com\/(?:watch\?v=|embed\/|shorts\/))([\w-]{11})/);
  if (yt) return "https://www.youtube.com/embed/" + yt[1];
  const vimeo = url.match(/vimeo\.com\/(\d+)/);
  if (vimeo) return "https://player.vimeo.com/video/" + vimeo[1];
  return null;
}

const emptyDrill = { title: "", category: "Putting", videoUrl: "", notes: "" };

function DrillLibrary({ isOwner }) {
  const [drills, setDrills] = useState([]);
  const [favorites, setFavorites] = useState([]);
  const [loading, setLoading] = useState(true);
  const [tab, setTab] = useState("all");
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState(emptyDrill);
  const [error, setError] = useState("");

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const res = await window.storage.get("golf-drills-v1", false);
        if (!cancelled && res && res.value) setDrills(JSON.parse(res.value));
      } catch (e) {
        // no drills saved yet
      }
      try {
        const favRes = await window.storage.get("golf-drill-favorites-v1", false);
        if (!cancelled && favRes && favRes.value) setFavorites(JSON.parse(favRes.value));
      } catch (e) {
        // no favorites saved yet
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  async function persistDrills(next) {
    setDrills(next);
    try {
      await window.storage.set("golf-drills-v1", JSON.stringify(next), false);
    } catch (e) {
      setError("Couldn't save — try again.");
    }
  }

  async function persistFavorites(next) {
    setFavorites(next);
    try {
      await window.storage.set("golf-drill-favorites-v1", JSON.stringify(next), false);
    } catch (e) {
      // non-critical
    }
  }

  function addDrill() {
    if (!form.title.trim() || !form.videoUrl.trim()) {
      setError("Add a title and a video link.");
      return;
    }
    const drill = {
      id: "d_" + Date.now(),
      title: form.title.trim(),
      category: form.category,
      videoUrl: form.videoUrl.trim(),
      notes: form.notes.trim(),
    };
    persistDrills([drill, ...drills]);
    setForm(emptyDrill);
    setShowForm(false);
    setError("");
  }

  function removeDrill(id) {
    persistDrills(drills.filter((d) => d.id !== id));
    if (favorites.includes(id)) persistFavorites(favorites.filter((f) => f !== id));
  }

  function toggleFavorite(id) {
    if (favorites.includes(id)) persistFavorites(favorites.filter((f) => f !== id));
    else persistFavorites([...favorites, id]);
  }

  if (loading) {
    return (
      <div style={{ background: COLORS.paper, minHeight: 400, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "'IBM Plex Sans', sans-serif", color: COLORS.inkSoft }}>
        <Loader2 size={18} style={{ marginRight: 8, animation: "spin 1s linear infinite" }} />
        Loading the drill library…
        <style>{"@keyframes spin { to { transform: rotate(360deg); } }"}</style>
      </div>
    );
  }

  const shown = tab === "favourites" ? drills.filter((d) => favorites.includes(d.id)) : drills;

  return (
    <div style={{ background: COLORS.paper, color: COLORS.ink, minHeight: "100%", fontFamily: "'IBM Plex Sans', system-ui, sans-serif", padding: "20px 20px 60px" }}>
      <style>{
        "@import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,600;9..144,700&family=IBM+Plex+Sans:wght@400;500;600&display=swap');" +
        "input, select, textarea { font-family: 'IBM Plex Sans', sans-serif; }" +
        "input:focus, select:focus, textarea:focus { outline: 2px solid " + COLORS.brandDeep + "; outline-offset: 1px; }" +
        "button:focus-visible { outline: 2px solid " + COLORS.brandDeep + "; outline-offset: 2px; }"
      }</style>

      <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 18 }}>
        <JCBadge size={40} />
        <div>
          <div style={{ fontFamily: "'Fraunces', serif", fontWeight: 600, fontSize: 15 }}>Drill Library</div>
          <div style={{ fontSize: 11, color: COLORS.inkSoft }}>{isOwner ? "Training videos from Joe Coyle" : "Browse and save your favourite drills"}</div>
        </div>
      </div>

      <div style={{ display: "flex", gap: 6, marginBottom: 20 }}>
        <TabButton active={tab === "all"} onClick={() => setTab("all")} icon={<Video size={14} />} label="All Drills" />
        <TabButton active={tab === "favourites"} onClick={() => setTab("favourites")} icon={<Heart size={14} />} label="My Favourites" />
      </div>

      {isOwner && (
        !showForm ? (
          <button
            onClick={() => setShowForm(true)}
            style={{
              display: "flex",
              alignItems: "center",
              gap: 6,
              background: COLORS.brandDeep,
              color: COLORS.paper,
              border: "none",
              borderRadius: 4,
              padding: "10px 16px",
              fontSize: 14,
              fontWeight: 500,
              cursor: "pointer",
              marginBottom: 22,
            }}
          >
            <Plus size={16} /> Upload a drill video
          </button>
        ) : (
          <div style={{ background: "#fff", border: "1px solid " + COLORS.line, borderRadius: 6, padding: 18, marginBottom: 22 }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
              <span style={{ fontFamily: "'Fraunces', serif", fontSize: 17, fontWeight: 600 }}>New drill</span>
              <button
                onClick={() => {
                  setShowForm(false);
                  setForm(emptyDrill);
                  setError("");
                }}
                style={{ background: "none", border: "none", cursor: "pointer", color: COLORS.inkSoft }}
              >
                <X size={18} />
              </button>
            </div>

            <FieldRow label="Title">
              <input type="text" value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} placeholder="e.g. Slow-motion takeaway drill" style={inputStyle} />
            </FieldRow>
            <FieldRow label="Category" style={{ marginTop: 12 }}>
              <select value={form.category} onChange={(e) => setForm({ ...form, category: e.target.value })} style={inputStyle}>
                {DRILL_CATEGORIES.map((c) => (
                  <option key={c} value={c}>{c}</option>
                ))}
              </select>
            </FieldRow>
            <FieldRow label="Video link (YouTube, Vimeo, or direct video URL)" style={{ marginTop: 12 }}>
              <input
                type="text"
                value={form.videoUrl}
                onChange={(e) => setForm({ ...form, videoUrl: e.target.value })}
                placeholder="https://youtube.com/watch?v=..."
                style={inputStyle}
              />
            </FieldRow>
            <FieldRow label="Notes" style={{ marginTop: 12 }}>
              <textarea
                value={form.notes}
                onChange={(e) => setForm({ ...form, notes: e.target.value })}
                placeholder="What this drill works on, setup, reps..."
                rows={3}
                style={{ ...inputStyle, resize: "vertical" }}
              />
            </FieldRow>

            {error && <div style={{ color: COLORS.alert, fontSize: 13, marginTop: 10 }}>{error}</div>}

            <button
              onClick={addDrill}
              style={{ marginTop: 14, width: "100%", background: COLORS.brandDeep, color: COLORS.paper, border: "none", borderRadius: 4, padding: "11px 16px", fontSize: 14, fontWeight: 500, cursor: "pointer" }}
            >
              Save drill
            </button>
          </div>
        )
      )}

      {shown.length === 0 ? (
        <div style={{ border: "1px dashed " + COLORS.line, borderRadius: 4, padding: "26px 18px", textAlign: "center", color: COLORS.inkSoft, fontSize: 14 }}>
          {tab === "favourites" ? "No favourites saved yet — tap the heart on a drill to save it here." : "No drills uploaded yet."}
        </div>
      ) : (
        DRILL_CATEGORIES.map((cat) => {
          const inCat = shown.filter((d) => d.category === cat);
          if (inCat.length === 0) return null;
          return (
            <div key={cat} style={{ marginBottom: 8 }}>
              <div style={{ fontFamily: "'Fraunces', serif", fontWeight: 600, fontSize: 17, color: COLORS.brandDeep, margin: "18px 0 10px" }}>{cat}</div>
              {inCat.map((d) => (
                <DrillCard key={d.id} drill={d} isFavorite={favorites.includes(d.id)} onToggleFavorite={() => toggleFavorite(d.id)} onRemove={() => removeDrill(d.id)} canRemove={isOwner} />
              ))}
            </div>
          );
        })
      )}
    </div>
  );
}

function DrillCard({ drill, isFavorite, onToggleFavorite, onRemove, canRemove }) {
  const embedUrl = toEmbedUrl(drill.videoUrl);
  return (
    <div style={{ background: "#fff", border: "1px solid " + COLORS.line, borderRadius: 6, marginBottom: 16, overflow: "hidden" }}>
      <div style={{ position: "relative", width: "100%", aspectRatio: "16/9", background: COLORS.ink }}>
        {embedUrl ? (
          <iframe
            src={embedUrl}
            title={drill.title}
            allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
            allowFullScreen
            style={{ width: "100%", height: "100%", border: "none" }}
          />
        ) : (
          <video controls src={drill.videoUrl} style={{ width: "100%", height: "100%", objectFit: "contain", background: COLORS.ink }} />
        )}
      </div>
      <div style={{ padding: "12px 14px" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 10 }}>
          <div>
            <div style={{ fontFamily: "'Fraunces', serif", fontSize: 15, fontWeight: 600 }}>{drill.title}</div>
            <div style={{ fontSize: 11, color: COLORS.brandDeep, marginTop: 2 }}>{drill.category}</div>
          </div>
          <div style={{ display: "flex", gap: 6, flexShrink: 0 }}>
            <button
              onClick={onToggleFavorite}
              style={{
                background: isFavorite ? COLORS.brandDeep : "none",
                border: "1px solid " + (isFavorite ? COLORS.brandDeep : COLORS.line),
                borderRadius: 20,
                padding: "6px 8px",
                cursor: "pointer",
                color: isFavorite ? COLORS.paper : COLORS.inkSoft,
                display: "flex",
                alignItems: "center",
              }}
            >
              <Heart size={14} fill={isFavorite ? "currentColor" : "none"} />
            </button>
            {canRemove && (
              <button onClick={onRemove} style={{ background: "none", border: "1px solid " + COLORS.line, borderRadius: 20, padding: "6px 8px", cursor: "pointer", color: COLORS.inkSoft }}>
                <Trash2 size={14} />
              </button>
            )}
          </div>
        </div>
        {drill.notes && <div style={{ fontSize: 13, color: COLORS.inkSoft, marginTop: 8, lineHeight: 1.5 }}>{drill.notes}</div>}
      </div>
    </div>
  );
}

function resizeChatImage(file, maxWidth) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("Couldn't read file"));
    reader.onload = () => {
      const img = new window.Image();
      img.onerror = () => reject(new Error("Couldn't read image"));
      img.onload = () => {
        const scale = Math.min(1, maxWidth / img.width);
        const w = Math.round(img.width * scale);
        const h = Math.round(img.height * scale);
        const canvas = document.createElement("canvas");
        canvas.width = w;
        canvas.height = h;
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0, w, h);
        resolve(canvas.toDataURL("image/jpeg", 0.72));
      };
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
  });
}

function TeamChat() {
  const [username, setUsername] = useState(null);
  const [nameDraft, setNameDraft] = useState("");
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(true);
  const [text, setText] = useState("");
  const [attachment, setAttachment] = useState(null);
  const [showLinkInput, setShowLinkInput] = useState(false);
  const [linkDraft, setLinkDraft] = useState("");
  const [error, setError] = useState("");
  const [sending, setSending] = useState(false);
  const bottomRef = useState(() => ({ current: null }))[0];

  async function loadMessages() {
    try {
      const res = await window.storage.get("golf-team-chat-v1", true);
      if (res && res.value) setMessages(JSON.parse(res.value));
    } catch (e) {
      // no messages yet
    }
  }

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const nameRes = await window.storage.get("golf-chat-username-v1", false);
        if (!cancelled && nameRes && nameRes.value) setUsername(nameRes.value);
      } catch (e) {
        // no saved name yet
      }
      await loadMessages();
      if (!cancelled) setLoading(false);
    })();
    const interval = setInterval(loadMessages, 8000);
    return () => {
      cancelled = true;
      clearInterval(interval);
    };
  }, []);

  useEffect(() => {
    if (bottomRef.current) bottomRef.current.scrollIntoView({ block: "end" });
  }, [messages.length]);

  async function saveUsername() {
    if (!nameDraft.trim()) return;
    const name = nameDraft.trim();
    setUsername(name);
    try {
      await window.storage.set("golf-chat-username-v1", name, false);
    } catch (e) {
      // non-critical
    }
  }

  async function handlePhotoAttach(e) {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    setError("");
    try {
      const dataUrl = await resizeChatImage(file, 480);
      setAttachment({ kind: "image", dataUrl });
    } catch (err) {
      setError("Couldn't attach that photo — try a different one.");
    }
  }

  function attachLink() {
    if (!linkDraft.trim()) return;
    setAttachment({ kind: "link", url: linkDraft.trim() });
    setLinkDraft("");
    setShowLinkInput(false);
  }

  async function sendMessage() {
    if (!text.trim() && !attachment) return;
    setSending(true);
    setError("");
    const msg = {
      id: "m_" + Date.now(),
      author: username,
      text: text.trim(),
      attachment: attachment,
      ts: Date.now(),
    };
    try {
      const res = await window.storage.get("golf-team-chat-v1", true);
      const current = res && res.value ? JSON.parse(res.value) : [];
      const next = [...current, msg];
      const ok = await window.storage.set("golf-team-chat-v1", JSON.stringify(next), true);
      if (ok) {
        setMessages(next);
        setText("");
        setAttachment(null);
      } else {
        setError("Couldn't send — try again.");
      }
    } catch (e) {
      setError("Couldn't send — try again.");
    } finally {
      setSending(false);
    }
  }

  if (loading) {
    return (
      <div style={{ background: COLORS.paper, minHeight: 400, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "'IBM Plex Sans', sans-serif", color: COLORS.inkSoft }}>
        <Loader2 size={18} style={{ marginRight: 8, animation: "spin 1s linear infinite" }} />
        Loading Team Chat…
        <style>{"@keyframes spin { to { transform: rotate(360deg); } }"}</style>
      </div>
    );
  }

  if (!username) {
    return (
      <div style={{ background: COLORS.paper, minHeight: "100%", fontFamily: "'IBM Plex Sans', system-ui, sans-serif", padding: "20px 20px 60px" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 18 }}>
          <JCBadge size={40} />
          <div>
            <div style={{ fontFamily: "'Fraunces', serif", fontWeight: 600, fontSize: 15 }}>Team Chat</div>
            <div style={{ fontSize: 11, color: COLORS.inkSoft }}>Message other members</div>
          </div>
        </div>
        <div style={{ background: "#fff", border: "1px solid " + COLORS.line, borderRadius: 6, padding: 18 }}>
          <div style={{ fontFamily: "'Fraunces', serif", fontSize: 16, fontWeight: 600, marginBottom: 8 }}>What should we call you?</div>
          <div style={{ fontSize: 13, color: COLORS.inkSoft, marginBottom: 12 }}>This name shows next to your messages in the chat.</div>
          <input
            type="text"
            value={nameDraft}
            onChange={(e) => setNameDraft(e.target.value)}
            placeholder="Your name"
            style={inputStyle}
          />
          <button
            onClick={saveUsername}
            style={{ marginTop: 12, width: "100%", background: COLORS.brandDeep, color: COLORS.paper, border: "none", borderRadius: 4, padding: "11px 16px", fontSize: 14, fontWeight: 500, cursor: "pointer" }}
          >
            Join the chat
          </button>
        </div>
      </div>
    );
  }

  return (
    <div style={{ background: COLORS.paper, minHeight: "100%", fontFamily: "'IBM Plex Sans', system-ui, sans-serif", display: "flex", flexDirection: "column", height: "100%" }}>
      <style>{
        "@import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,600;9..144,700&family=IBM+Plex+Sans:wght@400;500;600&display=swap');" +
        "input, textarea { font-family: 'IBM Plex Sans', sans-serif; }" +
        "input:focus, textarea:focus { outline: 2px solid " + COLORS.brandDeep + "; outline-offset: 1px; }" +
        "button:focus-visible { outline: 2px solid " + COLORS.brandDeep + "; outline-offset: 2px; }"
      }</style>

      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "20px 20px 14px" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
          <JCBadge size={40} />
          <div>
            <div style={{ fontFamily: "'Fraunces', serif", fontWeight: 600, fontSize: 15 }}>Team Chat</div>
            <div style={{ fontSize: 11, color: COLORS.inkSoft }}>Chatting as {username}</div>
          </div>
        </div>
        <button onClick={loadMessages} style={{ background: "none", border: "1px solid " + COLORS.line, borderRadius: 20, padding: "6px 8px", cursor: "pointer", color: COLORS.inkSoft }}>
          <RefreshCw size={14} />
        </button>
      </div>

      <div style={{ flex: 1, overflowY: "auto", padding: "0 20px" }}>
        {messages.length === 0 ? (
          <div style={{ border: "1px dashed " + COLORS.line, borderRadius: 4, padding: "26px 18px", textAlign: "center", color: COLORS.inkSoft, fontSize: 14 }}>
            No messages yet — say hello to the group.
          </div>
        ) : (
          messages.map((m) => <ChatBubble key={m.id} message={m} isOwn={m.author === username} />)
        )}
        <div ref={bottomRef} />
      </div>

      <div style={{ padding: 16, borderTop: "1px solid " + COLORS.line, background: "#fff" }}>
        {attachment && (
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8, background: COLORS.paper, borderRadius: 4, padding: "6px 10px" }}>
            {attachment.kind === "image" ? (
              <img src={attachment.dataUrl} alt="attachment" style={{ width: 36, height: 36, objectFit: "cover", borderRadius: 4 }} />
            ) : (
              <Link2 size={16} color={COLORS.brandDeep} />
            )}
            <span style={{ fontSize: 12, color: COLORS.inkSoft, flex: 1, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
              {attachment.kind === "image" ? "Photo attached" : attachment.url}
            </span>
            <button onClick={() => setAttachment(null)} style={{ background: "none", border: "none", cursor: "pointer", color: COLORS.inkSoft }}>
              <X size={14} />
            </button>
          </div>
        )}

        {showLinkInput && (
          <div style={{ display: "flex", gap: 6, marginBottom: 8 }}>
            <input
              type="text"
              value={linkDraft}
              onChange={(e) => setLinkDraft(e.target.value)}
              placeholder="Paste a video or document link"
              style={{ ...inputStyle, flex: 1 }}
            />
            <button onClick={attachLink} style={{ background: COLORS.brandDeep, color: COLORS.paper, border: "none", borderRadius: 4, padding: "0 14px", cursor: "pointer" }}>
              Add
            </button>
          </div>
        )}

        {error && <div style={{ color: COLORS.alert, fontSize: 12, marginBottom: 8 }}>{error}</div>}

        <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
          <label style={{ cursor: "pointer", color: COLORS.inkSoft, display: "flex", padding: 6 }}>
            <ImageIcon size={20} />
            <input type="file" accept="image/*" onChange={handlePhotoAttach} style={{ display: "none" }} />
          </label>
          <button onClick={() => setShowLinkInput(!showLinkInput)} style={{ background: "none", border: "none", cursor: "pointer", color: COLORS.inkSoft, display: "flex", padding: 6 }}>
            <Paperclip size={20} />
          </button>
          <input
            type="text"
            value={text}
            onChange={(e) => setText(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") sendMessage();
            }}
            placeholder="Message the group…"
            style={{ ...inputStyle, flex: 1 }}
          />
          <button
            onClick={sendMessage}
            disabled={sending}
            style={{ background: COLORS.brandDeep, color: COLORS.paper, border: "none", borderRadius: "50%", width: 38, height: 38, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", flexShrink: 0 }}
          >
            <Send size={16} />
          </button>
        </div>
      </div>
    </div>
  );
}

function ChatBubble({ message, isOwn }) {
  const time = new Date(message.ts).toLocaleTimeString([], { hour: "numeric", minute: "2-digit" });
  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: isOwn ? "flex-end" : "flex-start", margin: "10px 0" }}>
      {!isOwn && <div style={{ fontSize: 11, color: COLORS.inkSoft, marginBottom: 3, marginLeft: 4 }}>{message.author}</div>}
      <div
        style={{
          maxWidth: "78%",
          background: isOwn ? COLORS.brandDeep : "#fff",
          color: isOwn ? COLORS.paper : COLORS.ink,
          border: isOwn ? "none" : "1px solid " + COLORS.line,
          borderRadius: 12,
          padding: message.attachment && message.attachment.kind === "image" ? 6 : "9px 13px",
        }}
      >
        {message.attachment && message.attachment.kind === "image" && (
          <img src={message.attachment.dataUrl} alt="shared" style={{ width: "100%", maxWidth: 240, borderRadius: 8, display: "block" }} />
        )}
        {message.attachment && message.attachment.kind === "link" && (
          <a
            href={message.attachment.url}
            target="_blank"
            rel="noreferrer"
            style={{
              display: "flex",
              alignItems: "center",
              gap: 6,
              padding: "6px 8px",
              marginBottom: message.text ? 6 : 0,
              background: isOwn ? "rgba(255,255,255,0.15)" : COLORS.paper,
              borderRadius: 6,
              color: isOwn ? COLORS.paper : COLORS.brandDeep,
              fontSize: 12,
              textDecoration: "none",
              wordBreak: "break-all",
            }}
          >
            <FileText size={14} style={{ flexShrink: 0 }} />
            {message.attachment.url}
          </a>
        )}
        {message.text && (
          <div style={{ fontSize: 14, lineHeight: 1.4, padding: message.attachment && message.attachment.kind === "image" ? "4px 4px 0" : 0 }}>{message.text}</div>
        )}
      </div>
      <div style={{ fontSize: 10, color: COLORS.muted, marginTop: 3 }}>{time}</div>
    </div>
  );
}

function MenuScreen({ onSelect }) {
  const [open, setOpen] = useState(true);

  const ITEMS = [
    { key: "profile", label: "My profile", hint: "Bio, photo, and handicap" },
    { key: "log", label: "Stat tracker", hint: "Log rounds and view reports" },
    { key: "drills", label: "Drill Library", hint: "Upload and save favourite training videos" },
    { key: "chat", label: "Team Chat", hint: "Message members, share photos, videos & docs" },
  ];

  return (
    <div
      style={{
        background: COLORS.ink,
        minHeight: "100%",
        fontFamily: "'IBM Plex Sans', system-ui, sans-serif",
        color: COLORS.paper,
        display: "flex",
        justifyContent: "center",
      }}
    >
      <style>{fontImport}</style>
      <div style={{ width: "100%", maxWidth: 420, padding: "48px 24px" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 36 }}>
          <JCImage size={36} />
          <div>
            <div style={{ fontFamily: "'Fraunces', serif", fontWeight: 600, fontSize: 17 }}>Joe Coyle Golf</div>
            <div style={{ fontSize: 12, color: COLORS.muted }}>Welcome back</div>
          </div>
        </div>

        <button
          onClick={() => setOpen(!open)}
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            width: "100%",
            background: COLORS.inkDeep,
            border: "1px solid " + COLORS.line,
            borderRadius: 8,
            padding: "13px 16px",
            color: COLORS.paper,
            fontSize: 15,
            fontWeight: 500,
            cursor: "pointer",
          }}
        >
          <span style={{ display: "flex", alignItems: "center", gap: 8 }}>
            <MenuIcon size={16} /> Menu
          </span>
          {open ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
        </button>

        {open && (
          <div
            style={{
              marginTop: 8,
              background: COLORS.inkDeep,
              border: "1px solid " + COLORS.line,
              borderRadius: 8,
              overflow: "hidden",
            }}
          >
            {ITEMS.map((item, i) => (
              <button
                key={item.key}
                onClick={() => onSelect(item.key)}
                style={{
                  display: "block",
                  width: "100%",
                  textAlign: "left",
                  background: "none",
                  border: "none",
                  borderTop: i > 0 ? "1px solid " + COLORS.line : "none",
                  padding: "14px 16px",
                  color: COLORS.paper,
                  cursor: "pointer",
                }}
              >
                <div style={{ fontSize: 15, fontWeight: 500 }}>{item.label}</div>
                <div style={{ fontSize: 12, color: COLORS.muted, marginTop: 2 }}>{item.hint}</div>
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

// ---------------------------------------------------------------
// AppShell: the post-login experience — Menu, then whichever
// screen the member picked (Tracker/Reports/Profile live inside
// the Tracker component's own tabs; Drills and Chat are separate).
// ---------------------------------------------------------------

const OWNER_EMAIL = "joe@jc60.co.uk";

export default function AppShell({ onLogOut }) {
  const [screen, setScreen] = useState("menu");
  const [trackerView, setTrackerView] = useState("log");
  const isOwner = !!(auth.currentUser && auth.currentUser.email && auth.currentUser.email.toLowerCase() === OWNER_EMAIL);

  function handleMenuSelect(key) {
    if (key === "drills" || key === "chat") {
      setScreen(key);
      return;
    }
    setTrackerView(key);
    setScreen("tracker");
  }

  function TopBar() {
    return (
      <div style={{ display: "flex", justifyContent: "space-between", padding: "10px 20px 0" }}>
        <button
          onClick={() => setScreen("menu")}
          style={{
            display: "flex",
            alignItems: "center",
            gap: 5,
            background: "none",
            border: "1px solid " + COLORS.line,
            borderRadius: 20,
            padding: "5px 12px",
            fontSize: 12,
            color: COLORS.inkSoft,
            cursor: "pointer",
          }}
        >
          Menu
        </button>
        <button
          onClick={onLogOut}
          style={{
            display: "flex",
            alignItems: "center",
            gap: 5,
            background: "none",
            border: "1px solid " + COLORS.line,
            borderRadius: 20,
            padding: "5px 12px",
            fontSize: 12,
            color: COLORS.inkSoft,
            cursor: "pointer",
          }}
        >
          <LogOut size={13} /> Log out
        </button>
      </div>
    );
  }

  if (screen === "tracker") {
    return (
      <div style={{ background: COLORS.paper, minHeight: "100%" }}>
        <TopBar />
        <Tracker initialView={trackerView} key={trackerView} />
      </div>
    );
  }

  if (screen === "drills") {
    return (
      <div style={{ background: COLORS.paper, minHeight: "100%" }}>
        <TopBar />
        <DrillLibrary isOwner={isOwner} />
      </div>
    );
  }

  if (screen === "chat") {
    return (
      <div style={{ background: COLORS.paper, minHeight: "100%", display: "flex", flexDirection: "column" }}>
        <TopBar />
        <div style={{ flex: 1, display: "flex" }}>
          <TeamChat />
        </div>
      </div>
    );
  }

  return <MenuScreen onSelect={handleMenuSelect} />;
}
